paragraph.math:
$$X\mathbf{\beta} = \textbf{y}\text{,~}\quad\text{where~}X = \begin{bmatrix}
      1 & x_{1} \\
      1 & x_{2} \\
       \vdots & \vdots \\
      1 & x_{n}
      \end{bmatrix}\text{,~}\quad\mathbf{\beta} = \left\lbrack \begin{array}{r}
      \beta_{0} \\
      \beta_{1}
      \end{array} \right\rbrack\text{,~}\quad\textbf{y} = \begin{bmatrix}
      y_{1} \\
      y_{2} \\
       \vdots \\
      y_{n}
      \end{bmatrix}$$

$$\begin{matrix}
      \begin{array}{cclcccc}
      \begin{bmatrix}
      y_{1} \\
      y_{2} \\
       \vdots \\
      y_{n}
      \end{bmatrix} & = & & \begin{bmatrix}
      1 & x_{1} & x_{1}^{2} \\
      1 & x_{2} & x_{2}^{2} \\
       \vdots & \vdots & \vdots \\
      1 & x_{n} & x_{n}^{2}
      \end{bmatrix} & \left\lbrack \begin{array}{r}
      \beta_{0} \\
      \beta_{1} \\
      \beta_{2}
      \end{array} \right\rbrack & + & \begin{bmatrix}
      \epsilon_{1} \\
      \epsilon_{2} \\
       \vdots \\
      \epsilon_{n}
      \end{bmatrix} \\
      \textbf{y} & = & & X & \mathbf{\beta} & + & \mathbf{\epsilon}
      \end{array}
      \end{matrix}$$

$$\begin{matrix}
      \begin{matrix}
       & & \text{Observation} & & & \text{Design} & & & \text{Parameter} & & & \text{Residual} \\
       & & \text{vector} & & & \text{matrix} & & & \text{vector} & & & \text{vector} \\
      \textbf{y} & = & {\left\lbrack \begin{array}{r}
      y_{1} \\
      y_{2} \\
       \vdots \\
      y_{n}
      \end{array} \right\rbrack\text{,~}} & X & = & {\left\lbrack \begin{array}{rrrr}
      1 & x_{1} & x_{1}^{2} & x_{1}^{3} \\
      1 & x_{2} & x_{2}^{2} & x_{2}^{3} \\
       \vdots & \vdots & \vdots & \vdots \\
      1 & x_{n} & x_{n}^{2} & x_{n}^{3}
      \end{array} \right\rbrack\text{,~}} & \mathbf{\beta} & = & {\left\lbrack \begin{array}{r}
      \beta_{0} \\
      \beta_{1} \\
      \beta_{2} \\
      \beta_{3}
      \end{array} \right\rbrack\text{,~}} & \mathbf{\epsilon} & = & \left\lbrack \begin{array}{r}
      \epsilon_{1} \\
      \epsilon_{2} \\
       \vdots \\
      \epsilon_{n}
      \end{array} \right\rbrack
      \end{matrix} \\

      \end{matrix}$$

$$\begin{matrix}
      \begin{matrix}
       & & \text{Observation} & & & \text{Design} & & & \text{Parameter} & & & \text{Residual} \\
       & & \text{vector} & & & \text{matrix} & & & \text{vector} & & & \text{vector} \\
      \textbf{y} & = & {\left\lbrack \begin{array}{r}
      y_{1} \\
      y_{2} \\
       \vdots \\
      y_{n}
      \end{array} \right\rbrack\text{,~}} & X & = & {\left\lbrack \begin{array}{rrr}
      1 & u_{1} & v_{1} \\
      1 & u_{2} & v_{2} \\
       \vdots & \vdots & \vdots \\
      1 & u_{n} & v_{n}
      \end{array} \right\rbrack\text{,~~}} & \mathbf{\beta} & = & {\left\lbrack \begin{array}{r}
      \beta_{0} \\
      \beta_{1} \\
      \beta_{2}
      \end{array} \right\rbrack\text{,~}} & \mathbf{\epsilon} & = & \left\lbrack \begin{array}{r}
      \epsilon_{1} \\
      \epsilon_{2} \\
       \vdots \\
      \epsilon_{n}
      \end{array} \right\rbrack
      \end{matrix} \\

      \end{matrix}$$
